files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --accent-pressed: #b8334a;
  --border: #0f3460;
  --success: #4ecca3;
  --danger: #e94560;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: linear-gradient(45deg, #1a1a2e 25%, #16213e 25%, #16213e 50%, #1a1a2e 50%, #1a1a2e 75%, #16213e 75%, #16213e 100%);
  background-size: 40px 40px;
}

.card {
  background: var(--card-bg);
  border: 3px solid var(--border);
  border-radius: 0;
  box-shadow: 6px 6px 0 var(--border), 10px 10px 0 rgba(0,0,0,0.3);
  padding: 24px;
  max-width: 600px;
  width: 100%;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.9rem;
  color: var(--text);
  opacity: 0.8;
  margin-bottom: 20px;
}

h2 {
  font-size: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  margin-bottom: 12px;
  border-bottom: 2px solid var(--border);
  padding-bottom: 4px;
}

.expense-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
}

select, input {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 12px;
  background: var(--bg);
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: 0;
  outline: none;
  transition: border-color 0.1s;
}

select:focus, input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 20px;
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  background: var(--accent);
  color: #fff;
  box-shadow: 4px 4px 0 var(--border);
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
  min-height: 48px;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--border);
  background: var(--accent-pressed);
}

.btn.small {
  font-size: 0.8rem;
  padding: 6px 12px;
  min-height: 36px;
  box-shadow: 2px 2px 0 var(--border);
}

.btn.small:active {
  transform: translate(2px, 2px);
}

.btn.danger {
  background: var(--danger);
}

.btn.danger:hover {
  background: #ff6b81;
}

.error {
  color: var(--danger);
  font-size: 0.9rem;
  min-height: 1.5em;
  font-weight: 600;
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.expense-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  flex-wrap: wrap;
}

.expense-info {
  flex: 1;
  min-width: 120px;
  font-size: 0.95rem;
}

.expense-info strong {
  color: var(--accent);
}

.empty-state {
  text-align: center;
  opacity: 0.6;
  font-style: italic;
  padding: 16px;
}

.summary {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.summary-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  flex-wrap: wrap;
  gap: 4px;
  font-size: 0.95rem;
}

.summary-item .name {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
}

.summary-item .paid {
  opacity: 0.8;
}

.summary-item .balance {
  font-weight: 700;
}

.summary-item .balance.owed {
  color: var(--success);
}

.summary-item .balance.owes {
  color: var(--danger);
}

.summary-item .balance.settled {
  color: var(--text);
  opacity: 0.7;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 var(--border), 6px 6px 0 rgba(0,0,0,0.3);
  }
  h1 {
    font-size: 1.4rem;
  }
  .expense-item, .summary-item {
    flex-direction: column;
    align-items: flex-start;
  }
  .btn.small {
    align-self: flex-end;
  }
}

const FRIENDS = ['Alice', 'Bob', 'Charlie'];

let expenses = [];

const form = document.getElementById('expense-form');
const payerSelect = document.getElementById('payer');
const amountInput = document.getElementById('amount');
const labelInput = document.getElementById('label');
const errorMessage = document.getElementById('error-message');
const expenseList = document.getElementById('expense-list');
const emptyState = document.getElementById('empty-state');
const summaryDiv = document.getElementById('summary');

function formatMoney(amount) {
  return '$' + amount.toFixed(2);
}

function renderExpenses() {
  expenseList.innerHTML = '';
  if (expenses.length === 0) {
    emptyState.style.display = 'block';
    return;
  }
  emptyState.style.display = 'none';
  expenses.forEach((exp, index) => {
    const li = document.createElement('li');
    li.className = 'expense-item';
    const info = document.createElement('span');
    info.className = 'expense-info';
    info.innerHTML = `<strong>${exp.payer}</strong> paid ${formatMoney(exp.amount)}${exp.label ? ' — ' + exp.label : ''}`;
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'btn small danger';
    removeBtn.textContent = 'Remove';
    removeBtn.setAttribute('aria-label', `Remove expense: ${exp.payer} paid ${formatMoney(exp.amount)}${exp.label ? ' for ' + exp.label : ''}`);
    removeBtn.addEventListener('click', () => removeExpense(index));
    li.appendChild(info);
    li.appendChild(removeBtn);
    expenseList.appendChild(li);
  });
}

function renderSummary() {
  const total = expenses.reduce((sum, exp) => sum + exp.amount, 0);
  const share = total / FRIENDS.length;
  const paid = {};
  FRIENDS.forEach(f => paid[f] = 0);
  expenses.forEach(exp => { paid[exp.payer] += exp.amount; });

  summaryDiv.innerHTML = '';
  FRIENDS.forEach(friend => {
    const balance = paid[friend] - share;
    const div = document.createElement('div');
    div.className = 'summary-item';
    let balanceText, balanceClass;
    if (Math.abs(balance) < 0.005) {
      balanceText = 'settled';
      balanceClass = 'settled';
    } else if (balance > 0) {
      balanceText = `is owed ${formatMoney(balance)}`;
      balanceClass = 'owed';
    } else {
      balanceText = `owes ${formatMoney(-balance)}`;
      balanceClass = 'owes';
    }
    div.innerHTML = `
      <span class="name">${friend}</span>
      <span class="paid">paid ${formatMoney(paid[friend])}</span>
      <span class="balance ${balanceClass}">${balanceText}</span>
    `;
    summaryDiv.appendChild(div);
  });
}

function addExpense(payer, amount, label) {
  expenses.push({ payer, amount, label });
  renderExpenses();
  renderSummary();
}

function removeExpense(index) {
  expenses.splice(index, 1);
  renderExpenses();
  renderSummary();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  errorMessage.textContent = '';
  const payer = payerSelect.value;
  const amount = parseFloat(amountInput.value);
  const label = labelInput.value.trim();

  if (isNaN(amount) || amount <= 0) {
    errorMessage.textContent = 'Please enter a positive amount.';
    amountInput.focus();
    return;
  }
  if (!FRIENDS.includes(payer)) {
    errorMessage.textContent = 'Invalid payer.';
    return;
  }

  addExpense(payer, amount, label);
  amountInput.value = '';
  labelInput.value = '';
  amountInput.focus();
});

// Initial render
renderExpenses();
renderSummary();
